def brokerage(trade_value, segment, broker="discount"):
    if broker == "discount":
        if segment == "equity_delivery":
            return 0.0
        # ₹20 flat or 0.03% of turnover, whichever is lower
        return min(20.0, 0.0003 * trade_value)
    elif broker == "full_service":
        return 0.005 * trade_value
    else:
        raise ValueError(f"Unknown broker type: {broker}")
